param(
    [switch]$SkipCheck
)

$ErrorActionPreference = "Stop"

Write-Host ""
Write-Host "============================================================" -ForegroundColor DarkYellow
Write-Host " HOGWARTS ONLINE - PRODUCT REWORK V2" -ForegroundColor Yellow
Write-Host " Current MMO + Gamification + PC + Mobile + Core Loop" -ForegroundColor Gray
Write-Host "============================================================" -ForegroundColor DarkYellow
Write-Host ""

$root = Get-Location
$required = @(
    "server.js",
    "HogwartsCore.js",
    "HogwartsMMOEngine.js",
    "GamificacaoHogwarts.js",
    "index.html",
    "package.json"
)

foreach ($file in $required) {
    if (!(Test-Path (Join-Path $root $file))) {
        throw "Execute este patch na raiz da versao atualizada do projeto. Faltou: $file"
    }
}

if (-not (Get-Command node -ErrorAction SilentlyContinue)) {
    throw "Node.js nao foi encontrado no PATH."
}

# Verificacao de que esta e a geracao atualizada, nao a versao antiga.
$mmo = Get-Content "HogwartsMMOEngine.js" -Raw
$gam = Get-Content "GamificacaoHogwarts.js" -Raw
if ($mmo -notmatch "HogwartsMMOEngine" -or $gam -notmatch "CATALOGO_CONQUISTAS") {
    throw "Esta pasta nao parece ser a versao atualizada auditada. O patch foi interrompido sem alterar nada."
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backup = Join-Path $root ".hogwarts-product-v2-backup-$stamp"
New-Item -ItemType Directory -Path $backup -Force | Out-Null

$backupFiles = @(
    "server.js",
    "HogwartsCore.js",
    "HogwartsMMOEngine.js",
    "GamificacaoHogwarts.js",
    "index.html",
    "package.json",
    "site.html"
)

foreach ($file in $backupFiles) {
    if (Test-Path $file) {
        Copy-Item $file (Join-Path $backup $file) -Force
    }
}

Write-Host "[1/4] Backup completo criado." -ForegroundColor Cyan
Write-Host "      $backup" -ForegroundColor DarkGray

$patcherPath = Join-Path $root ".hogwarts-product-v2-patcher.js"

$patcherBase64 = ""
$patcherBytes = [Convert]::FromBase64String($patcherBase64)
[IO.File]::WriteAllBytes($patcherPath, $patcherBytes)

try {
    Write-Host "[2/4] Aplicando rework integrado..." -ForegroundColor Cyan
    node $patcherPath
    if ($LASTEXITCODE -ne 0) { throw "O transformador V2 retornou codigo $LASTEXITCODE." }

    # Rollback aponta para este backup exato.
    $rollback = @"
param()
`$ErrorActionPreference = "Stop"
`$root = Split-Path -Parent `$MyInvocation.MyCommand.Path
`$backup = "$backup"
if (!(Test-Path `$backup)) { throw "Backup nao encontrado: `$backup" }

foreach (`$file in @("server.js","HogwartsCore.js","HogwartsMMOEngine.js","GamificacaoHogwarts.js","index.html","package.json","site.html")) {
    `$src = Join-Path `$backup `$file
    if (Test-Path `$src) {
        Copy-Item `$src (Join-Path `$root `$file) -Force
    }
}

foreach (`$generated in @("product","scripts\preflight-v2.js","PRODUCT_V2.md")) {
    `$target = Join-Path `$root `$generated
    if (Test-Path `$target) { Remove-Item `$target -Recurse -Force }
}

Write-Host "Rollback Product V2 concluido." -ForegroundColor Yellow
"@
    [IO.File]::WriteAllText(
        (Join-Path $root "ROLLBACK_HOGWARTS_PRODUCT_V2.ps1"),
        $rollback,
        (New-Object Text.UTF8Encoding($false))
    )

    Write-Host "[3/4] Validando sintaxe..." -ForegroundColor Cyan
    $syntaxFiles = @(
        "server.js",
        "HogwartsCore.js",
        "GamificacaoHogwarts.js",
        "product/server-product-v2.js",
        "product/client-product-v2.js",
        "scripts/preflight-v2.js"
    )

    foreach ($file in $syntaxFiles) {
        node --check $file
        if ($LASTEXITCODE -ne 0) {
            throw "Erro de sintaxe detectado em $file"
        }
    }

    if (-not $SkipCheck) {
        Write-Host "[4/4] Rodando preflight de produto..." -ForegroundColor Cyan
        npm run check
        if ($LASTEXITCODE -ne 0) {
            Write-Host ""
            Write-Host "O rework foi aplicado, mas o preflight encontrou um ponto." -ForegroundColor Yellow
            Write-Host "Use ROLLBACK_HOGWARTS_PRODUCT_V2.ps1 somente se quiser reverter." -ForegroundColor Yellow
            exit 1
        }
    }

    Write-Host ""
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host " HOGWARTS PRODUCT V2 APLICADO E VALIDADO" -ForegroundColor Green
    Write-Host "============================================================" -ForegroundColor Green
    Write-Host ""
    Write-Host "Configure no .env:" -ForegroundColor White
    Write-Host "  SESSION_SECRET=<chave longa aleatoria>" -ForegroundColor Gray
    Write-Host "  ADMIN_PLAYER_ID=BRX_..." -ForegroundColor Gray
    Write-Host "  APP_ORIGIN=https://seu-dominio  (opcional em local)" -ForegroundColor Gray
    Write-Host ""
    Write-Host "Depois:" -ForegroundColor White
    Write-Host "  npm install" -ForegroundColor Cyan
    Write-Host "  npm start" -ForegroundColor Cyan
    Write-Host ""
    Write-Host "Contas antigas precisarao entrar novamente uma vez para receber a sessao V2." -ForegroundColor DarkGray
}
catch {
    Write-Host ""
    Write-Host "ERRO: $($_.Exception.Message)" -ForegroundColor Red
    Write-Host "O backup esta em: $backup" -ForegroundColor Yellow
    throw
}
finally {
    if (Test-Path $patcherPath) {
        Remove-Item $patcherPath -Force -ErrorAction SilentlyContinue
    }
}
